css:
.pinball-toggle-box {
  position: relative;
  width: 160px;
  height: 70px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.pinball-toggle-box .pinball-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

.pinball-track {
  position: relative;
  width: 136px;
  height: 52px;
  background: linear-gradient(180deg, #18191c 0%, #222428 100%);
  border-radius: 26px;
  cursor: pointer;
  border: 1px solid #111214;
  box-shadow:
    inset 0 4px 8px rgba(0, 0, 0, 0.8),
    inset 0 1px 2px rgba(0, 0, 0, 0.6),
    0 1px 0 rgba(255, 255, 255, 0.03);
  display: flex;
  align-items: center;
  padding: 0 6px;
  box-sizing: border-box;
  overflow: hidden;
}

.pinball-rail {
  position: absolute;
  left: 20px;
  width: 96px;
  height: 4px;
  background: #0f1012;
  border-radius: 2px;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.05);
  pointer-events: none;
}

.forge-spring {
  position: absolute;
  width: 14px;
  height: 18px;
  background: repeating-linear-gradient(
    90deg,
    #3a3d46 0px,
    #3a3d46 2px,
    #1c1d22 3px,
    #1c1d22 5px
  );
  border-radius: 2px;
  pointer-events: none;
}
.spring-left {
  left: 8px;
  transform-origin: left;
}
.spring-right {
  right: 8px;
  transform-origin: right;
}

.pinball-core {
  position: absolute;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: radial-gradient(
    circle at 35% 35%,
    #ffffff 0%,
    #a2a6b0 45%,
    #4b4e54 80%,
    #1c1d20 100%
  );
  box-shadow:
    0 4px 8px rgba(0, 0, 0, 0.4),
    0 1px 2px rgba(0, 0, 0, 0.4),
    inset 0 -2px 5px rgba(0, 0, 0, 0.4);
  z-index: 5;
  pointer-events: none;
  transform: translateX(0);
}

.pinball-input:checked ~ .pinball-track .pinball-core {
  animation: launch-right 0.45s cubic-bezier(0.25, 1, 0.5, 1) forwards;
}

.pinball-input:checked ~ .pinball-track .spring-right {
  animation: spring-absorb-right 0.45s ease-out;
}

.pinball-input:not(:checked) ~ .pinball-track .pinball-core {
  animation: launch-left 0.45s cubic-bezier(0.25, 1, 0.5, 1) forwards;
}

.pinball-input:not(:checked) ~ .pinball-track .spring-left {
  animation: spring-absorb-left 0.45s ease-out;
}

@keyframes launch-right {
  0% {
    transform: translateX(0);
  }
  35% {
    transform: translateX(92px);
  }
  55% {
    transform: translateX(82px);
  }
  75% {
    transform: translateX(90px);
  }
  100% {
    transform: translateX(88px);
  }
}

@keyframes launch-left {
  0% {
    transform: translateX(88px);
  }
  35% {
    transform: translateX(-4px);
  }
  55% {
    transform: translateX(6px);
  }
  75% {
    transform: translateX(-1px);
  }
  100% {
    transform: translateX(0);
  }
}

@keyframes spring-absorb-right {
  0% {
    transform: scaleX(1);
  }
  35% {
    transform: scaleX(0.35);
  }
  60% {
    transform: scaleX(1.1);
  }
  100% {
    transform: scaleX(1);
  }
}

@keyframes spring-absorb-left {
  0% {
    transform: scaleX(1);
  }
  35% {
    transform: scaleX(0.35);
  }
  60% {
    transform: scaleX(1.1);
  }
  100% {
    transform: scaleX(1);
  }
}
